{
  # sh-tea — transparent pipeline stage logger (tee pun). scout module.
  # Thin import of the standalone sh-tea flake (github:mikenrafter/sh-tea);
  # see that repo for the actual Rust CLI + packaging logic.
  # home-files drops a minimal ~/.config/tea/config.toml (just the keys this
  # host wants to pin — tea's own Rust-level defaults fill in the rest, see
  # apply_raw() in that repo's src/lib.rs).
  #
  # `inputs ? nix-scout` gates scout/home: true under nix-scout eval/switch,
  # false under flakelet path eval — facets stay definitionally exclusive.

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
  inputs.nix-scout.url = "github:mikenrafter/nix-scout";
  inputs.nix-scout.inputs.nixpkgs.follows = "nixpkgs";
  inputs.sh-tea.url = "github:mikenrafter/sh-tea";
  inputs.sh-tea.inputs.nixpkgs.follows = "nixpkgs";

  outputs = { nixpkgs, ... }@inputs:
  let
    system = "x86_64-linux";
    lib = nixpkgs.lib;
  in
  lib.optionalAttrs (inputs ? nix-scout) (
    let
      pkgs = import nixpkgs {
        inherit system;
        overlays = [ inputs.sh-tea.overlays.default ];
      };

      # Host default: don't bother logging auto-activated stages that finish
      # in under 5s — only worth a paper trail if something upstream was
      # actually slow (nix build/eval, nixos-rebuild, ...). Doesn't apply to
      # --tea/TEA_FORCE, which always log regardless of duration.
      configToml = pkgs.writeText "tea-config.toml" ''
        [defaults]
        min-duration-ms = 5000
      '';

      homeFiles = pkgs.runCommand "scout-sh-tea-home" { } ''
        mkdir -p $out/home-files/.config/tea
        cp ${configToml} $out/home-files/.config/tea/config.toml
      '';
    in {
      # scout
      # home
      # symlinkJoin (not buildEnv): buildEnv's pathsToLink symlinks whole
      # top-level dirs (home-files/.config would be a directory symlink),
      # but nix-scout's apply-hm.sh walks home-files with plain `find` (no
      # -L) expecting real directories with symlinks only at leaf files —
      # exactly what symlinkJoin's deep merge produces. See break-lock's
      # scout module for the same pattern.
      packages.${system}.scout = pkgs.symlinkJoin {
        name = "scout-sh-tea";
        paths = [
          pkgs.sh-tea
          homeFiles
        ];
      };
    }
  ) // {
    # flakelet
  };
}

