183	fn as_bool(val: &toml::Value, default: bool) -> bool {
184	    match val {
185	        toml::Value::Boolean(b) => *b,
186	        toml::Value::Integer(i) => *i != 0,
187	        toml::Value::Float(f) => *f != 0.0,
188	        toml::Value::String(s) => {
189	            let s = s.trim().to_lowercase();
190	            match s.as_str() {
191	                "1" | "true" | "yes" | "on" => true,
192	                "0" | "false" | "no" | "off" => false,
193	                _ => default,
