303	
304	const SHELL_NAMES: &[&str] = &["bash", "sh", "dash", "zsh", "ksh", "mksh", "fish"];
305	
306	const TERMINAL_EMULATOR_COMM_SUBSTRINGS: &[&str] = &[
307	    "warp",
308	    "kitty",
309	    "alacritty",
310	    "wezterm",
311	    "ghostty",
312	    "hyper",
313	    "foot",
314	    "terminology",
315	    "konsole",
