317	    "xfce4-terminal",
318	    "tilix",
319	    "contour",
320	    "tabby",
321	];
322	
323	fn process_comm(pid: i32) -> Option<String> {
324	    fs::read_to_string(format!("/proc/{pid}/comm"))
325	        .ok()
326	        .map(|s| s.trim().to_string())
327	}
328	
329	fn process_cmdline_argv(pid: i32) -> Vec<String> {
330	    let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) else {
331	        return Vec::new();
332	    };
333	    raw.split(|b: &u8| *b == 0)
334	        .filter(|s| !s.is_empty())
335	        .filter_map(|s| std::str::from_utf8(s).ok().map(str::to_string))
336	        .collect()
337	}
338	
339	fn process_ppid(pid: i32) -> Option<i32> {
340	    let stat = fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
341	    let parts: Vec<&str> = stat.split_whitespace().collect();
342	    parts.get(3)?.parse().ok()
343	}
344	
345	fn argv0_base(argv: &[String]) -> String {
346	    argv.first()
347	        .map(|a| {
348	            Path::new(a)
349	                .file_name()
350	                .and_then(|n| n.to_str())
351	                .unwrap_or(a)
352	                .to_string()
353	        })
354	        .unwrap_or_default()
355	}
