361	fn comm_is_terminal_emulator(comm: &str) -> bool {
362	    let low = comm.trim().to_lowercase();
363	    TERMINAL_EMULATOR_COMM_SUBSTRINGS
364	        .iter()
365	        .any(|s| low.contains(s))
