368	fn term_program_is_emulator() -> bool {
369	    env::var("TERM_PROGRAM")
370	        .ok()
371	        .filter(|v| !v.trim().is_empty())
372	        .is_some_and(|tp| {
373	            let low = tp.to_lowercase();
374	            TERMINAL_EMULATOR_COMM_SUBSTRINGS
375	                .iter()
376	                .any(|s| low.contains(s))
377	                || low.ends_with("terminal")
378	        })
