391	}
392	
393	pub fn parent_comm() -> Option<String> {
394	    let ppid = unsafe { libc::getppid() };
395	    process_comm(ppid)
396	}
397	
398	pub fn parent_cmdline_display() -> String {
399	    let ppid = unsafe { libc::getppid() };
400	    let argv = process_cmdline_argv(ppid);
401	    if argv.is_empty() {
402	        return "-".into();
403	    }
404	    argv.join(" ")
405	}
406	
407	fn shell_level() -> Option<u32> {
408	    env::var("SHLVL").ok().and_then(|v| v.parse().ok())
409	}
410	
411	/// Warp and similar terminals spawn nested shell layers (InitShell bootstrap,
412	/// command substitutions) before running internal sed/tr/od pipelines. User
413	/// pipeline stages inherit SHLVL from the interactive shell (~2–4); internal
414	/// tooling is much deeper (the Warp echo path observed SHLVL=5).
415	fn is_terminal_emulator_deep_subprocess() -> bool {
416	    if !term_program_is_emulator() {
417	        return false;
418	    }
419	    shell_level().is_some_and(|level| level >= 5)
420	}
421	
422	pub fn shell_level_display() -> String {
423	    shell_level()
424	        .map(|n| n.to_string())
425	        .unwrap_or_else(|| "-".into())
426	}
427	
428	fn shell_argv_has_dash_c(argv: &[String]) -> bool {
429	    if argv.is_empty() {
430	        return false;
431	    }
432	    if !SHELL_NAMES.iter().any(|s| *s == argv0_base(argv).as_str()) {
433	        return false;
434	    }
435	    argv.iter().any(|a| a == "-c")
436	}
437	
438	/// True when the immediate parent is the user's shell (or a shell `-c` one
439	/// level below another shell). Terminal emulators' internal `sh -c` pipelines
440	/// (Warp paste handling, etc.) are excluded.
441	pub fn tea_user_pipe_set() -> bool {
442	    env_truthy("TEA_USER_PIPE")
443	}
444	
445	pub fn is_user_pipeline_stage() -> bool {
446	    if tea_user_pipe_set() {
447	        return true;
448	    }
449	
450	    // Under TERM_PROGRAM (Warp, etc.) session fish is the parent of both user
451	    // pipelines and terminal input-engine internals — parent/SHLVL heuristics
452	    // cannot tell them apart. Require the fish hook's TEA_USER_PIPE there.
453	    if term_program_is_emulator() {
454	        return false;
455	    }
456	
457	    let ppid = unsafe { libc::getppid() };
458	    if ppid <= 1 {
459	        return false;
460	    }
461	    let Some(parent_comm) = process_comm(ppid) else {
462	        return false;
463	    };
464	    let parent_argv = process_cmdline_argv(ppid);
465	    let parent_base = argv0_base(&parent_argv);
466	
467	    // Interactive fish (no `-c`) parents tab-completion helpers — e.g.
468	    // `__fish_complete_pids` pipes to `tail -n +2` when completing `kill` —
469	    // that pass parent/TTY heuristics but are not user pipelines. Real fish
470	    // pipes set TEA_USER_PIPE via the vendor_conf.d preexec hook (above).
471	    if parent_comm.trim() == "fish" && !shell_argv_has_dash_c(&parent_argv) {
472	        return false;
473	    }
474	
475	    if is_terminal_emulator_deep_subprocess() {
476	        return false;
477	    }
478	
479	    // Terminal emulators and make/recipes spawn filters via POSIX sh/dash, not
480	    // the user's fish/bash pipeline executor.
481	    if matches!(parent_base.as_str(), "sh" | "dash") {
482	        return false;
483	    }
484	
485	    if !comm_is_shell(&parent_comm) {
486	        return false;
487	    }
488	
489	    if shell_argv_has_dash_c(&parent_argv) {
490	        // Warp uses bash/sh -c for internal pipelines; fish -c is still a user shell.
491	        if term_program_is_emulator() && parent_base != "fish" {
492	            return false;
493	        }
494	        let Some(gppid) = process_ppid(ppid) else {
495	            return false;
496	        };
497	        let Some(gp_comm) = process_comm(gppid) else {
498	            return false;
499	        };
500	        if comm_is_terminal_emulator(&gp_comm) {
501	            return false;
502	        }
503	        return comm_is_shell(&gp_comm);
504	    }
505	    true
506	}
507	
508	/// Returns true when the immediate parent process is a shell executing a script
509	/// file (e.g. `bash /path/to/nix-scout`). Used to suppress activation for tools
510	/// called from within a script's internals, as opposed to a user or agent typing
511	/// the command directly.
512	pub fn parent_is_running_script() -> bool {
513	    let ppid = unsafe { libc::getppid() };
514	    if ppid <= 1 {
515	        return false;
516	    }
517	    let Ok(raw) = fs::read(format!("/proc/{ppid}/cmdline")) else {
518	        return false;
519	    };
520	    if raw.is_empty() {
521	        return false;
522	    }
523	    let argv: Vec<&str> = raw
524	        .split(|b: &u8| *b == 0)
525	        .filter(|s| !s.is_empty())
526	        .filter_map(|s| std::str::from_utf8(s).ok())
527	        .collect();
528	    if argv.is_empty() {
529	        return false;
530	    }
531	    let argv0_base = Path::new(argv[0])
532	        .file_name()
533	        .and_then(|n| n.to_str())
534	        .unwrap_or("");
535	    if !SHELL_NAMES.iter().any(|s| *s == argv0_base) {
536	        return false;
537	    }
538	    // Walk shell arguments looking for a script-file positional.
539	    // Bail on -c (command string, not a file) or -- (end of options).
540	    let mut i = 1;
541	    while i < argv.len() {
542	        let arg = argv[i];
543	        if arg == "--" {
544	            break;
545	        }
546	        if arg == "-c" {
547	            // Command string follows, not a script path — not a script invocation.
548	            return false;
549	        }
550	        if arg.starts_with('-') {
551	            i += 1;
552	            continue;
553	        }
554	        // First non-flag argument: treat it as the script path.
555	        return Path::new(arg).is_file();
556	    }
557	    false
558	}
