560	fn is_interactive_session_inner(simulate_piped_stdin: bool) -> bool {
561	    if env_truthy("TEA_INTERACTIVE") {
562	        return true;
563	    }
564	    if env::var("CI").map(|v| !v.trim().is_empty()).unwrap_or(false) {
565	        return false;
566	    }
567	    // Stderr being a TTY means we're in a terminal, but that's not enough: stdin
568	    // must also be non-TTY (i.e. actually piped) so we don't activate when a
569	    // subprocess of a non-piped command happens to inherit the terminal.
570	    let stderr_tty = unsafe { libc::isatty(libc::STDERR_FILENO) == 1 };
571	    let stdin_tty = if simulate_piped_stdin {
572	        false
573	    } else {
574	        unsafe { libc::isatty(libc::STDIN_FILENO) == 1 }
575	    };
576	    stderr_tty && !stdin_tty
577	}
