680	/// Single activation gate shared by `tea-wrap` and `tea which`.
681	pub fn evaluate_activation(
682	    tool: &str,
683	    cfg: &Config,
684	    force_on: bool,
685	    force_off: bool,
686	    ctx: ActivationContext,
687	) -> ActivationReport {
688	    let tcfg = tool_config(cfg, tool);
689	    let factors = collect_activation_factors(ctx, &tcfg);
690	
691	    if force_off {
692	        return ActivationReport {
693	            activate: false,
694	            outcome: ActivationOutcome::SuppressedForceOff,
695	            factors,
696	        };
697	    }
698	    if force_on {
699	        return ActivationReport {
700	            activate: true,
701	            outcome: ActivationOutcome::ActivatedForceTea,
702	            factors,
703	        };
704	    }
705	    if env_truthy("TEA_OFF") {
706	        return ActivationReport {
707	            activate: false,
708	            outcome: ActivationOutcome::SuppressedTeaOff,
709	            factors,
710	        };
711	    }
712	    if env_truthy("TEA_FORCE") {
713	        return ActivationReport {
714	            activate: true,
715	            outcome: ActivationOutcome::ActivatedTeaForce,
716	            factors,
717	        };
718	    }
719	    if factors.systemd_suppress {
720	        return ActivationReport {
721	            activate: false,
722	            outcome: ActivationOutcome::SuppressedSystemd,
723	            factors,
724	        };
725	    }
726	    if !tcfg.enabled {
727	        return ActivationReport {
728	            activate: false,
729	            outcome: ActivationOutcome::SuppressedDisabled,
730	            factors,
731	        };
732	    }
733	    if tcfg.only_in_git_repos && !factors.in_git_repo {
734	        return ActivationReport {
735	            activate: false,
736	            outcome: ActivationOutcome::SuppressedOnlyInGitRepos,
737	            factors,
738	        };
739	    }
740	    if tcfg.only_outside_git_repos && factors.in_git_repo {
741	        return ActivationReport {
742	            activate: false,
743	            outcome: ActivationOutcome::SuppressedOnlyOutsideGitRepos,
744	            factors,
745	        };
746	    }
747	    if tcfg.manual_only {
748	        return ActivationReport {
749	            activate: false,
750	            outcome: ActivationOutcome::SuppressedManualOnly,
751	            factors,
752	        };
753	    }
754	    if factors.parent_script {
755	        return ActivationReport {
756	            activate: false,
757	            outcome: ActivationOutcome::SuppressedParentScript,
758	            factors,
759	        };
760	    }
761	
762	    if factors.user_pipeline {
763	        if factors.agentic {
764	            return ActivationReport {
765	                activate: true,
766	                outcome: ActivationOutcome::ActivatedAgentic,
767	                factors,
768	            };
769	        }
770	        if factors.default_interactive && factors.interactive_session {
771	            return ActivationReport {
772	                activate: true,
773	                outcome: ActivationOutcome::ActivatedInteractive,
774	                factors,
775	            };
776	        }
777	    }
778	
779	    ActivationReport {
780	        activate: false,
781	        outcome: ActivationOutcome::SuppressedNotAuto,
782	        factors,
783	    }
784	}
