786	pub fn is_agentic() -> bool {
787	    if env_truthy("TEA_AGENT") {
788	        return true;
789	    }
790	    for key in AGENT_ENV_MARKERS {
791	        if let Ok(val) = env::var(key) {
792	            if !env_falsey_or_empty(&val) {
793	                return true;
794	            }
795	        }
796	    }
797	    let mut pid = unsafe { libc::getppid() };
798	    for _ in 0..8 {
799	        if pid <= 1 {
800	            break;
801	        }
802	        if let Ok(comm) = fs::read_to_string(format!("/proc/{pid}/comm")) {
803	            if comm_looks_agent(&comm) {
804	                return true;
805	            }
806	        }
807	        if let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) {
808	            let argv0 = raw
809	                .split(|b| *b == 0)
810	                .next()
811	                .and_then(|b| std::str::from_utf8(b).ok())
812	                .unwrap_or("");
813	            let name = Path::new(argv0)
814	                .file_name()
815	                .and_then(|n| n.to_str())
816	                .unwrap_or("");
817	            if basename_looks_agent(name) {
818	                return true;
819	            }
820	        }
821	        let Ok(stat) = fs::read_to_string(format!("/proc/{pid}/stat")) else {
822	            break;
823	        };
824	        let parts: Vec<&str> = stat.split_whitespace().collect();
825	        if parts.len() < 4 {
826	            break;
827	        }
828	        match parts[3].parse::<i32>() {
829	            Ok(ppid) => pid = ppid,
830	            Err(_) => break,
831	        }
832	    }
833	    false
834	}
