853	pub fn strip_tea_flags(argv: &[String]) -> (Vec<String>, bool, bool) {
854	    let mut out = Vec::new();
855	    let mut force_on = false;
856	    let mut force_off = false;
857	    let mut i = 0;
858	    while i < argv.len() {
859	        let a = &argv[i];
860	        if a == "--tea" {
861	            force_on = true;
862	        } else if a == "--no-tea" || a == "--coffee" {
863	            force_off = true;
864	        } else if a == "--" {
865	            out.push(a.clone());
866	            out.extend(argv[i + 1..].iter().cloned());
867	            break;
868	        } else {
869	            out.push(a.clone());
870	        }
871	        i += 1;
872	    }
873	    (out, force_on, force_off)
874	}
