924	fn display_cmdline(parts: &[String]) -> Option<String> {
925	    for (i, p) in parts.iter().enumerate() {
926	        let base = Path::new(p)
927	            .file_name()
928	            .and_then(|n| n.to_str())
929	            .unwrap_or("");
930	        if base == "tea-wrap" && i + 2 < parts.len() {
931	            let tool = &parts[i + 1];
932	            let args = &parts[i + 3..];
933	            return Some(format_argv(tool, args));
934	        }
935	    }
936	    let base0 = Path::new(&parts[0])
937	        .file_name()
938	        .and_then(|n| n.to_str())
939	        .unwrap_or("");
940	    if matches!(
941	        base0,
942	        "bash" | "fish" | "zsh" | "sh" | "dash" | "nu" | "python" | "python3"
943	    ) {
944	        return None;
945	    }
946	    Some(
947	        parts
948	            .iter()
949	            .map(|p| shell_quote(p))
950	            .collect::<Vec<_>>()
951	            .join(" "),
952	    )
953	}
