955	pub fn discover_pipeline_siblings() -> Vec<(i32, String)> {
956	    let pgid = unsafe { libc::getpgid(0) };
957	    let my_ppid = unsafe { libc::getppid() };
958	    if pgid < 0 {
959	        return Vec::new();
960	    }
961	    let my_pid = process::id() as i32;
962	    let mut found = Vec::new();
963	
964	    let Ok(entries) = fs::read_dir("/proc") else {
965	        return Vec::new();
966	    };
967	    for entry in entries.flatten() {
968	        let name = entry.file_name();
969	        let name = name.to_string_lossy();
970	        if !name.chars().all(|c| c.is_ascii_digit()) {
971	            continue;
972	        }
973	        let Ok(pid) = name.parse::<i32>() else {
974	            continue;
975	        };
976	        let g = unsafe { libc::getpgid(pid) };
977	        if g != pgid {
978	            continue;
979	        }
980	        let Ok(stat) = fs::read_to_string(format!("/proc/{pid}/stat")) else {
981	            continue;
982	        };
983	        let parts: Vec<&str> = stat.split_whitespace().collect();
984	        if parts.len() < 4 {
985	            continue;
986	        }
987	        let Ok(ppid) = parts[3].parse::<i32>() else {
988	            continue;
989	        };
990	        if ppid != my_ppid && pid != my_pid {
991	            continue;
992	        }
993	        let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) else {
994	            continue;
995	        };
996	        if raw.is_empty() {
997	            continue;
998	        }
999	        let argv: Vec<String> = raw
1000	            .split(|b| *b == 0)
1001	            .filter(|p| !p.is_empty())
1002	            .map(|p| String::from_utf8_lossy(p).into_owned())
1003	            .collect();
1004	        if argv.is_empty() {
1005	            continue;
1006	        }
1007	        if let Some(display) = display_cmdline(&argv) {
1008	            found.push((pid, display));
1009	        }
1010	    }
1011	    found.sort_by_key(|(pid, _)| *pid);
1012	    found
1013	}
