1015	pub fn highlight_command(
1016	    tool: &str,
1017	    args: &[String],
1018	    siblings: Option<&[(i32, String)]>,
1019	) -> String {
1020	    let stage = format_argv(tool, args);
1021	    let marked = format!("⟦{stage}⟧");
1022	    let owned;
1023	    let sibs = match siblings {
1024	        Some(s) => s,
1025	        None => {
1026	            owned = discover_pipeline_siblings();
1027	            &owned
1028	        }
1029	    };
1030	    if sibs.len() <= 1 {
1031	        return marked;
1032	    }
1033	    let me = process::id() as i32;
1034	    let mut pieces = Vec::new();
1035	    for (pid, cmd) in sibs {
1036	        if *pid == me {
1037	            pieces.push(marked.clone());
1038	        } else {
1039	            pieces.push(cmd.clone());
1040	        }
1041	    }
1042	    if pieces.len() <= 1 {
1043	        return marked;
1044	    }
1045	    pieces.join(" | ")
1046	}
