1048	pub fn ensure_gitignore(cwd: &Path, tcfg: &ToolCfg) {
1049	    if !tcfg.update_gitignore {
1050	        return;
1051	    }
1052	    let Some(root) = git_root(Some(cwd)) else {
1053	        return;
1054	    };
1055	    let gi = root.join(".gitignore");
1056	    let needed = ["logs.csv"];
1057	    let existing = if gi.is_file() {
1058	        fs::read_to_string(&gi).unwrap_or_default()
1059	    } else {
1060	        String::new()
1061	    };
1062	    let present: HashSet<String> = existing
1063	        .lines()
1064	        .map(|ln| ln.trim().to_string())
1065	        .collect();
1066	    let mut to_add = Vec::new();
1067	    for item in needed {
1068	        let mut variants: HashSet<String> = HashSet::new();
1069	        variants.insert(item.to_string());
1070	        variants.insert(format!("/{item}"));
1071	        variants.insert(format!("./{item}"));
1072	        if present.is_disjoint(&variants) {
1073	            to_add.push(item);
1074	        }
1075	    }
1076	    if to_add.is_empty() {
1077	        return;
1078	    }
1079	    let mut f = match OpenOptions::new().create(true).append(true).open(&gi) {
1080	        Ok(f) => f,
1081	        Err(exc) => {
1082	            eprintln!("tea: warning: could not update .gitignore: {exc}");
1083	            return;
1084	        }
1085	    };
1086	    if !existing.is_empty() && !existing.ends_with('\n') {
1087	        let _ = writeln!(f);
1088	    }
1089	    if !present.iter().any(|p| p.contains("# tea")) {
1090	        let _ = writeln!(f, "\n# tea — transparent pipeline logs");
1091	    }
1092	    for item in to_add {
1093	        let _ = writeln!(f, "{item}");
1094	    }
1095	}
