1122	fn parse_csv_rows(raw: &str) -> Vec<CsvRow> {
1123	    let mut rows = Vec::new();
1124	    if raw.trim().is_empty() {
1125	        return rows;
1126	    }
1127	    let mut rdr = csv::ReaderBuilder::new()
1128	        .flexible(true)
1129	        .from_reader(raw.as_bytes());
1130	    let headers: Vec<String> = match rdr.headers() {
1131	        Ok(h) => h.iter().map(|s| s.to_string()).collect(),
1132	        Err(_) => return rows,
1133	    };
1134	    for record in rdr.records().flatten() {
1135	        let mut row = HashMap::new();
1136	        for (i, field) in record.iter().enumerate() {
1137	            if let Some(key) = headers.get(i) {
1138	                row.insert(key.clone(), field.to_string());
1139	            }
1140	        }
1141	        rows.push(row);
1142	    }
1143	    rows
1144	}
