1149	    }
1150	    let Ok(f) = File::open(csv_path) else {
1151	        return Vec::new();
1152	    };
1153	    flock_sh(f.as_raw_fd());
1154	    let mut raw = String::new();
1155	    let mut fref = &f;
1156	    let _ = fref.read_to_string(&mut raw);
1157	    let rows = parse_csv_rows(&raw);
1158	    flock_un(f.as_raw_fd());
1159	    rows
1160	}
