1174	fn timestamp_now() -> String {
1175	    unsafe {
1176	        let mut t: libc::time_t = 0;
1177	        libc::time(&mut t);
1178	        let tm = libc::localtime(&t);
1179	        if tm.is_null() {
1180	            return "1970-01-01T00:00:00+0000".into();
1181	        }
1182	        let mut buf = [0u8; 64];
1183	        let n = libc::strftime(
1184	            buf.as_mut_ptr() as *mut libc::c_char,
1185	            buf.len(),
1186	            b"%Y-%m-%dT%H:%M:%S%z\0".as_ptr() as *const libc::c_char,
1187	            tm,
1188	        );
1189	        if n == 0 {
1190	            return "1970-01-01T00:00:00+0000".into();
1191	        }
1192	        String::from_utf8_lossy(&buf[..n as usize]).into_owned()
1193	    }
1194	}
1195	
1196	/// Create logfile via `mktemp --suffix .tea` → $TMPDIR/tmp.XXXXXX.tea (often /tmp).
1197	pub fn make_logfile_path() -> io::Result<PathBuf> {
1198	    let output = process::Command::new("mktemp")
1199	        .arg("--suffix")
1200	        .arg(".tea")
1201	        .output()?;
1202	    if !output.status.success() {
1203	        return Err(io::Error::other(format!(
1204	            "mktemp failed: {}",
1205	            String::from_utf8_lossy(&output.stderr)
1206	        )));
1207	    }
1208	    let path = String::from_utf8_lossy(&output.stdout).trim().to_string();
1209	    if path.is_empty() {
1210	        return Err(io::Error::other("mktemp returned empty path"));
1211	    }
1212	    Ok(PathBuf::from(path))
1213	}
1214	
1215	pub fn register_log(
1216	    tool: &str,
1217	    args: &[String],
1218	    logfile: &Path,
1219	    nbytes: u64,
1220	    exit_code: i32,
1221	    tcfg: &ToolCfg,
1222	    cwd: Option<&Path>,
1223	    siblings: Option<&[(i32, String)]>,
1224	) -> io::Result<CsvRow> {
1225	    let cwd = cwd
1226	        .map(Path::to_path_buf)
1227	        .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
1228	    let index_path = csv_path(Some(&cwd));
1229	    ensure_gitignore(&cwd, tcfg);
1230	
1231	    let command = format_argv(tool, args);
1232	    let highlighted = highlight_command(tool, args, siblings);
1233	    let ts = timestamp_now();
1234	
1235	    if let Some(parent) = index_path.parent() {
1236	        fs::create_dir_all(parent)?;
1237	    }
1238	
1239	    let mut f = OpenOptions::new()
1240	        .read(true)
1241	        .write(true)
1242	        .create(true)
1243	        .truncate(false)
1244	        .open(&index_path)?;
1245	    flock_ex(f.as_raw_fd());
1246	
1247	    let result = (|| {
1248	        f.seek(SeekFrom::Start(0))?;
1249	        let mut raw = String::new();
1250	        f.read_to_string(&mut raw)?;
1251	
1252	        let mut rows = parse_csv_rows(&raw);
1253	        let new_id = next_id(&rows);
1254	
1255	        // Captures live under TMPDIR (/tmp); store absolute path.
1256	        let log_stored = logfile
1257	            .canonicalize()
1258	            .unwrap_or_else(|_| logfile.to_path_buf())
1259	            .to_string_lossy()
1260	            .into_owned();
1261	
1262	        let mut row = HashMap::new();
1263	        row.insert("id".into(), new_id.to_string());
1264	        row.insert("timestamp".into(), ts);
1265	        row.insert("cwd".into(), cwd.to_string_lossy().into_owned());
1266	        row.insert("tool".into(), tool.to_string());
1267	        row.insert("command".into(), command);
1268	        row.insert("highlighted".into(), highlighted);
1269	        row.insert("logfile".into(), log_stored);
1270	        row.insert("bytes".into(), nbytes.to_string());
1271	        row.insert("exit_code".into(), exit_code.to_string());
1272	        rows.push(row.clone());
1273	
1274	        let max_n = tcfg.max_log_records.max(1);
1275	        while rows.len() > max_n {
1276	            let old = rows.remove(0);
1277	            if let Some(old_log) = old.get("logfile") {
1278	                if !old_log.is_empty() {
1279	                    let p = {
1280	                        let p = PathBuf::from(old_log);
1281	                        if p.is_absolute() {
1282	                            p
1283	                        } else {
1284	                            cwd.join(p)
1285	                        }
1286	                    };
1287	                    let _ = fs::remove_file(p);
1288	                }
1289	            }
1290	        }
1291	
1292	        f.seek(SeekFrom::Start(0))?;
1293	        f.set_len(0)?;
1294	        {
1295	            let mut wtr = csv::WriterBuilder::new()
1296	                .terminator(csv::Terminator::Any(b'\n'))
1297	                .from_writer(&mut f);
1298	            wtr.write_record(CSV_FIELDS)?;
1299	            for r in &rows {
1300	                let vals: Vec<&str> = CSV_FIELDS
1301	                    .iter()
1302	                    .map(|k| r.get(*k).map(|s| s.as_str()).unwrap_or(""))
1303	                    .collect();
1304	                wtr.write_record(&vals)?;
1305	            }
1306	            wtr.flush()?;
1307	        }
1308	        f.sync_all()?;
1309	        Ok(row)
1310	    })();
1311	
1312	    flock_un(f.as_raw_fd());
1313	    result
1314	}
1315	
1316	pub fn announce(row: &CsvRow, quiet: bool) {
1317	    if quiet || env_truthy("TEA_QUIET") {
1318	        return;
1319	    }
1320	    let id = row.get("id").map(|s| s.as_str()).unwrap_or("?");
1321	    let logfile = row.get("logfile").map(|s| s.as_str()).unwrap_or("?");
1322	    let command = row.get("command").map(|s| s.as_str()).unwrap_or("?");
1323	    eprintln!("[tea] --id {id} {logfile} | {command}");
1324	}
1325	
1326	pub fn list_rows(cwd: Option<&Path>) -> Vec<CsvRow> {
1327	    read_csv_rows(&csv_path(cwd))
1328	}
1329	
1330	pub fn last_row(cwd: Option<&Path>) -> Option<CsvRow> {
1331	    list_rows(cwd).pop()
1332	}
1333	
1334	/// Copy stdin to both the child process stdin and the logfile.
1335	pub fn copy_stdin_to_proc_and_log(
1336	    proc_stdin: &mut impl Write,
1337	    log_f: &mut impl Write,
1338	) -> io::Result<u64> {
1339	    let mut stdin = io::stdin().lock();
1340	    let mut buf = [0u8; 65536];
1341	    let mut nbytes = 0u64;
1342	    loop {
1343	        let n = stdin.read(&mut buf)?;
1344	        if n == 0 {
1345	            break;
1346	        }
1347	        log_f.write_all(&buf[..n])?;
1348	        nbytes += n as u64;
1349	        if let Err(e) = proc_stdin.write_all(&buf[..n]) {
1350	            if e.kind() == io::ErrorKind::BrokenPipe {
1351	                break;
1352	            }
1353	            return Err(e);
1354	        }
1355	    }
1356	    log_f.flush()?;
1357	    Ok(nbytes)
1358	}
