{
  # nix-scout CLI — scout module.
  # `inputs ? nix-scout` gates scout/home; flakelet section reserved in the // merge.

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
  inputs.nix-scout.url = "github:mikenrafter/nix-scout";
  inputs.nix-scout.inputs.nixpkgs.follows = "nixpkgs";

  outputs = { nixpkgs, ... }@inputs:
  let
    system = "x86_64-linux";
    lib = nixpkgs.lib;
  in
  lib.optionalAttrs (inputs ? nix-scout) (
    let
      pkgs = import nixpkgs {
        inherit system;
        overlays = [ inputs.nix-scout.overlays.default ];
      };
    in {
      # scout
      packages.${system}.scout = pkgs.buildEnv {
        name = "scout-nix-scout";
        paths = [
          pkgs.nix-scout
        ];
        pathsToLink = [ "/bin" "/lib" "/share" ];
      };
      # home
    }
  ) // {
    # flakelet
  };
}
