{
  # break-lock — scout module.
  # Thin import of the standalone break-lock flake (github:mikenrafter/break-lock).
  # home-files drops DMS+niri-flavored ~/.config/break-lock/config.json for this host.
  # The flake also exports homeManagerModules.default (unused here — see that repo).
  #
  # `inputs ? nix-scout` gates scout/home: true under nix-scout eval/switch,
  # false under flakelet path eval — facets stay definitionally exclusive.

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-26.05";
  inputs.nix-scout.url = "github:mikenrafter/nix-scout";
  inputs.nix-scout.inputs.nixpkgs.follows = "nixpkgs";
  inputs.break-lock.url = "github:mikenrafter/break-lock";
  inputs.break-lock.inputs.nixpkgs.follows = "nixpkgs";

  outputs = { nixpkgs, ... }@inputs:
  let
    system = "x86_64-linux";
    lib = nixpkgs.lib;
  in
  lib.optionalAttrs (inputs ? nix-scout) (
    let
      pkgs = import nixpkgs {
        inherit system;
        overlays = [ inputs.break-lock.overlays.default ];
      };

      # Host defaults: DankMaterialShell lock IPC + niri monitor power.
      hostConfig = {
        lock = "dms ipc lock lock";
        unlock = "dms ipc lock unlock";
        is_locked = "dms ipc lock isLocked";
        screen_off = "niri msg action power-off-monitors";
        screen_on = "niri msg action power-on-monitors";
        notify = ''notify-send -t 2500 -u low -r 42 "$BREAK_LOCK_MSG"'';
        base_minutes = 5;
        step_minutes = 3;
        queue_commit_secs = 3;
        peek_window_secs = 3;
        peek_timeout_secs = 30;
      };

      configJson = pkgs.writeText "break-lock-config.json" (builtins.toJSON hostConfig);

      homeFiles = pkgs.runCommand "scout-break-lock-home" { } ''
        mkdir -p $out/home-files/.config/break-lock
        cp ${configJson} $out/home-files/.config/break-lock/config.json
      '';
    in {
      # scout
      # home
      packages.${system}.scout = pkgs.symlinkJoin {
        name = "scout-break-lock";
        paths = [
          pkgs.break-lock
          homeFiles
        ];
      };
    }
  ) // {
    # flakelet
  };
}

