            --bind "$_tmp/profiles" /nix/var/nix/profiles/per-user \
            --bind "$_tmp/gcroots"  /nix/var/nix/gcroots/per-user \
            --die-with-parent \
            -- "''${@:-$SHELL}"
          rm -rf "$_tmp"
        }
      '';
    };
  };
