/// Runtime-defined extra wraps from `TEA_EXTRA_TOOLS`: comma- or
/// whitespace-separated `name=path` pairs pointing at the real binary
/// (a Nix store outpath, usually). Consumed by `load_tools()` (so `tea-wrap`
/// and `tea which` accept the names) and by the fish hook
/// (share/fish/vendor_conf.d/tea-extra-tools.fish), which creates shadow
/// functions calling `tea-wrap name path` in interactive shells only.
pub fn parse_extra_tools(raw: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    for pair in raw.split(|c: char| c == ',' || c.is_whitespace()) {
        let pair = pair.trim();
        if pair.is_empty() {
            continue;
        }
        let Some((name, real)) = pair.split_once('=') else {
            continue;
        };
        let name = name.trim();
        let real = real.trim();
        if name.is_empty() || real.is_empty() {
            continue;
        }
        if !out.iter().any(|(n, _)| n == name) {
            out.push((name.to_string(), real.to_string()));
        }
    }
    out
}

pub fn extra_tools() -> Vec<(String, String)> {
    env::var("TEA_EXTRA_TOOLS")
        .map(|raw| parse_extra_tools(&raw))
        .unwrap_or_default()
}
